for (const item of $input.all()) {
  try {
    let text = item.json.output || item.json.text || "";
    if (typeof text === 'string') {
      let cleanStr = text.replace(/```json|```/g, '').trim();
      item.json.affordances = JSON.parse(cleanStr);
    }
  } catch (e) {
    item.json.error = "JSON parse error: " + e.message;
  }
}
return $input.all();

